const d=msg.payload;
if(typeof d!=='object'||d.suhu===undefined)return null;
d.received=new Date().toISOString();
const th=flow.get('threshold')||{max:30};
d.max=th.max;
d.alert=d.suhu>th.max;
flow.set('lastSensor',d);
const db={params:{$suhu:d.suhu,$kelembaban:d.kelembaban,$ts:d.timestamp,$received:d.received}};
const ws={payload:d};
const notif=d.alert?{topic:'iot/notifikasi',payload:{pesan:'Suhu '+d.suhu+' melewati batas '+th.max,suhu:d.suhu,waktu:d.received}}:null;
return [db,ws,notif];

const key=env.get('API_KEY')||'iot-kampus-123';
const b=msg.payload,p=msg.req.path,m=msg.req.method;
const th=()=>flow.get('threshold')||{max:30};
const r=(c,x)=>{msg.statusCode=c;msg.payload=x;return [msg,null,null];};
if(msg.req.headers['x-api-key']!==key)return r(401,{status:'error',message:'API key salah atau kosong'});
if(p==='/api/suhu')return r(200,{status:'success',data:flow.get('lastSensor')||{suhu:null,kelembaban:null,timestamp:null},threshold:th(),server_time:new Date().toISOString()});
if(p==='/api/history')return [null,msg,null];
if(p==='/api/threshold'){
 if(m!=='PUT')return r(200,{status:'success',threshold:th()});
 const max=parseFloat(b&&b.max);
 if(!isFinite(max))return r(400,{status:'error',message:'max wajib berupa angka'});
 flow.set('threshold',{max});
 return r(200,{status:'success',threshold:{max}});
}
if(p==='/api/kontrol'){
 if(!b||!b.device||!b.action)return r(400,{status:'error',message:'device dan action wajib diisi'});
 const o=r(200,{status:'success',message:'Perintah terkirim',sent:b});
 o[2]={topic:'iot/kontrol',payload:b};
 return o;
}
return r(404,{status:'error',message:'endpoint tidak ada'});
